package dev.hyperears.integration
import dev.hyperears.protocol.huawei.HuaweiFreebudsSppCodec as Wire
import org.junit.Assert.*
import org.junit.Test
class HuaweiPairedDevicesTest {
    // Generated by pinned OpenFreebuds HuaweiSppPackage.to_bytes, not our builder.
    private val a=hex("5a0021002b310201020301000406001122334455050109070101080101090550686f6e6576cc")
    private val b=hex("5a0022002b310201020301010406aabbccddeeff05010007010008010109064c6170746f707d4a")
    private fun hex(s:String)=s.chunked(2).map{it.toInt(16).toByte()}.toByteArray()
    @Test fun completeOrderedEnumerationAndSourceCommandGoldens() {
        val s=HuaweiDailySettingsSession(HuaweiDailyProfile.PRO3)
        assertTrue(s.queries().any{it.contentEquals(hex("5a0005002b310100f1ec"))})
        s.offer(Wire.parseFrame(b)!!);assertNull(s.state.pairedDevices)
        s.offer(Wire.parseFrame(a)!!)
        val snapshot=s.state.pairedDevices!!
        assertEquals(listOf("Phone","Laptop"),snapshot.devices.map{it.name})
        assertTrue(snapshot.devices[0].playing)
        val req=HuaweiDailyControlRequest.ManageDevice(snapshot,"001122334455",HuaweiPairedAction.FORGET)
        assertArrayEquals(hex("5a000b002b330306001122334455bfc9"),s.encode(req))
        assertEquals(req,ControlRequestTransport.decode(ControlRequestTransport.encode(req)))
        assertEquals(snapshot,s.state.pairedDevices)
        assertArrayEquals(hex("5a0005002b310100f1ec"),s.readback(req).single())
        assertNull(s.encode(req))
        s.offer(Wire.parseFrame(a)!!);assertNull(s.state.pairedDevices)
        s.offer(Wire.parseFrame(b)!!);assertNotEquals(snapshot,s.state.pairedDevices)
        assertNull(s.encode(req));s.reset();assertNull(s.state.pairedDevices)
    }
    @Test fun longUtf8NameWithinTlvLimitDoesNotBlockCompleteEnumeration() {
        val s=HuaweiDailySettingsSession(HuaweiDailyProfile.PRO3)
        val first=Wire.parseFrame(a)!!
        val name="设备".repeat(25) //150 UTF8 bytes, valid source field9.
        val params=first.params+(9 to name.toByteArray(Charsets.UTF_8))
        val framed=Wire.packet(0x2b31,params.entries.map{it.key to it.value})
        s.offer(Wire.parseFrame(framed)!!);assertNull(s.state.pairedDevices)
        s.offer(Wire.parseFrame(b)!!)
        val snapshot=s.state.pairedDevices!!
        assertEquals(name,snapshot.devices[0].name)
        assertNotNull(s.encode(HuaweiDailyControlRequest.ManageDevice(snapshot,"001122334455",HuaweiPairedAction.FORGET)))
    }
    @Test fun duplicateMacInconsistentCountAndNegativeIndicesRevokeUntilFreshQuery() {
        val s=HuaweiDailySettingsSession(HuaweiDailyProfile.PRO3)
        val first=Wire.parseFrame(a)!!;val second=Wire.parseFrame(b)!!
        s.offer(first);s.offer(second);assertNotNull(s.state.pairedDevices)
        s.queries();s.offer(first)
        s.offer(second.copy(params=second.params+(4 to first.params.getValue(4))))
        assertNull(s.state.pairedDevices)
        s.offer(second);assertNull(s.state.pairedDevices)
        s.queries();s.offer(first);s.offer(second.copy(params=second.params+(2 to byteArrayOf(3))))
        assertNull(s.state.pairedDevices)
        s.queries();s.offer(first.copy(params=first.params+(3 to byteArrayOf(-1))))
        s.offer(second);assertNull(s.state.pairedDevices)
        s.offer(first);assertNotNull(s.state.pairedDevices)
        val before=s.state.pairedDevices
        s.offer(first.copy(params=first.params+(127 to byteArrayOf(0))))
        assertEquals(before,s.state.pairedDevices)
        s.offer(first.copy(params=first.params+(9 to byteArrayOf(0xc0.toByte()))))
        assertEquals(before,s.state.pairedDevices)
    }
    @Test fun malformedRowsAckAndDisabledProfilesCannotGrantOrAutoWrite() {
        val off=HuaweiDailySettingsSession(HuaweiDailyProfile.STUDIO)
        off.offer(Wire.parseFrame(a)!!);off.offer(Wire.parseFrame(b)!!);assertNull(off.state.pairedDevices)
        val s=HuaweiDailySettingsSession(HuaweiDailyProfile.BUDS6I)
        s.offer(Wire.parseFrame(a)!!);s.offer(Wire.parseFrame(b)!!)
        val snapshot=s.state.pairedDevices!!
        assertNull(snapshot.devices[0].autoConnect)
        assertNull(s.encode(HuaweiDailyControlRequest.ManageDevice(snapshot,"001122334455",HuaweiPairedAction.ENABLE_AUTO)))
        s.offer(Wire.Frame(0x2b36,mapOf(127 to byteArrayOf(0)),byteArrayOf()))
        assertEquals(snapshot,s.state.pairedDevices)
        s.offer(Wire.Frame(0x2b36,emptyMap(),byteArrayOf()))
        assertNull(s.state.pairedDevices);assertEquals(1,s.drainCommands().size);assertTrue(s.drainCommands().isEmpty())
    }
}
